enum { NORMAL,EXACT_PM0,PENDING,RESERVED,EMPTY_ST0,EMPTY_STI };
enum { INTERIOR,EDGE,NO_READ,TRUNCATED,UNMAPPED };
enum { MAIN,CROSS,SPANS,EMPTY_GROUP,PM0_GROUP,PENDING_GROUP,RESERVED_GROUP,GROUPS };
enum { RAW,STATE,DECODE,EXECUTION,HOST,MEMORY,CATEGORIES };
static const uint64_t CODE=UINT64_C(0x7b00000),DATA=UINT64_C(0x7b10000),DENIED=UINT64_C(0x7b18000);
static unsigned checks,failures,executions,precision_cases,exact_cases,legacy_cases,empty_cases,memory_fault_cases;
static unsigned category_failures[CATEGORIES],group_cases[GROUPS];
static char phase[240]="setup";
static int check_kind(int ok,const char *what,unsigned category)
{++checks;if(!ok){++failures;++category_failures[category];if(failures<=80)fprintf(stderr,"FAIL %s: %s\n",phase,what);}return ok;}
static int check(int ok,const char *what){return check_kind(ok,what,STATE);}
static void put16(uint8_t *p,uint16_t n){p[0]=(uint8_t)n;p[1]=(uint8_t)(n>>8);}
static void put64(uint8_t *p,uint64_t n){for(unsigned i=0;i<8;++i)p[i]=(uint8_t)(n>>(8*i));}
typedef struct {uint16_t se;uint64_t sig,preview;unsigned tag;} raw_t;
typedef struct {raw_t raw;uint16_t status_bits;} answer_t;
typedef struct {const char *name;raw_t dst,src;uint64_t memory[4];answer_t expected[4];raw_t alias_seed;answer_t self[4];unsigned exact_preview_mask;} sample_t;
