    uint64_t address=DATA+64,window=DATA+48;uint8_t expected_mem[32],source[8];unsigned n=f->form->width,offset=16;
    snprintf(phase,sizeof(phase),"%s %s %s %s TOP=%u PC=%u RC=%u host=%u control=%u span=%u group=%u",f->ctx->arch==HB_ARCH_X86?"x86":"x64",f->jit?"JIT":"interp",f->form->name,s->name,top,pc,rc,host,control,span,group);
    memset(expected_mem,0xa5,sizeof(expected_mem));put64(source,s->memory[f->form->format]);
    if(span==EDGE||span==TRUNCATED){window=DATA+PAGE_BYTES-32;offset=32-f->form->width+(span==TRUNCATED);address=window+offset;if(span==TRUNCATED)--n;}
    else if(span==UNMAPPED){window=DATA+PAGE_BYTES-32;address=DATA+PAGE_BYTES+64;n=0;}
    else if(span==NO_READ){window=DENIED+48;address=DENIED+64;}
